def transform_v2(grid):
    from collections import Counter
    g = [r[:] for r in grid]
    H, W = len(g), len(g[0])

    # Find background
    cnt = Counter(x for r in g for x in r)
    bg = cnt.most_common(1)[0][0]

    # Find separator row
    separator_row = None
    for r in range(H):
        if all(g[r][c] != bg for c in range(W)):
            if len(set(g[r])) == 1:
                separator_row = r
                break

    # Find all special cells
    special_cells = []
    for r in range(H):
        for c in range(W):
            v = g[r][c]
            if v != bg and (separator_row is None or r != separator_row):
                special_cells.append((r, c))

    if not special_cells:
        return g

    # Create result
    result = [[0]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            if separator_row is not None and r == separator_row:
                result[r][c] = g[r][c]
            else:
                result[r][c] = bg

    # Find topmost special row
    topmost_special_row = min(r for r, c in special_cells)

    # Copy special cells down (for rows below topmost_special_row)
    for r, c in special_cells:
        if r > topmost_special_row:
            new_r = r  # stays in place
            if new_r < separator_row and new_r <= topmost_special_row:
                result[new_r][c] = g[r][c]
            elif new_r < separator_row:
                result[new_r][c] = g[r][c]

    # Let me try a different approach - copy cells to result based on their new positions
    # Special cell at grid position (r,c) moves to (r+1, c)
    for orig_r, orig_c in special_cells:
        new_r = orig_r + 1
        if new_r < separator_row:
            result[new_r][orig_c] = g[orig_r][orig_c]

    # Now set the topmost special row to all 8s
    for c in range(W):
        result[topmost_special_row][c] = 8

    return result

